/* 原书每天那行〔时价〕：米 28-86、盐 18-62、酒 3-14，一天两字节，base64 装起来。
   数据从《沈策古风剧情设定完整版》里逐行抽出，共 26,910 天，和游戏的 TOTAL_DAYS 对齐。 */
const PRICE_B64="";
const PRICE=(function(){
  let bin;
  try{bin=atob(PRICE_B64)}catch(e){return null}
  const n=bin.length>>1, a=new Uint8Array(n*3);
  for(let i=0;i<n;i++){
    const v=bin.charCodeAt(i*2)|(bin.charCodeAt(i*2+1)<<8);
    a[i*3]=28+Math.floor(v/540);
    a[i*3+1]=18+Math.floor((v%540)/12);
    a[i*3+2]=3+v%12;
  }
  return a;
})();
function priceOf(day){
  if(!PRICE)return null;
  const i=Math.max(1,Math.min(PRICE.length/3,day|0))-1;
  return [PRICE[i*3],PRICE[i*3+1],PRICE[i*3+2]];
}
